CREATE TABLE IF NOT EXISTS moonpark_pricing_data.audit_event ( audit_event_id bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY ( INCREMENT 1 START 1 MINVALUE 1 MAXVALUE 9223372036854775807 CACHE 1 ), actor character varying(150) COLLATE pg_catalog."default" NOT NULL, action character varying(50) COLLATE pg_catalog."default" NOT NULL, details character varying(1000) COLLATE pg_catalog."default", correlation_id character varying(100) COLLATE pg_catalog."default", created_date timestamp with time zone NOT NULL DEFAULT now(), CONSTRAINT audit_event_pkey PRIMARY KEY (audit_event_id) );
CREATE INDEX IF NOT EXISTS audit_event_created_date_idx ON moonpark_pricing_data.audit_event (created_date DESC);
CREATE INDEX IF NOT EXISTS audit_event_actor_created_date_idx ON moonpark_pricing_data.audit_event (actor, created_date DESC);

CREATE OR REPLACE FUNCTION moonpark_pricing_data.audit_event_block_change()
    RETURNS trigger
    LANGUAGE plpgsql
AS $$
BEGIN
    RAISE EXCEPTION 'audit_event is append-only';
END;
$$;

DROP TRIGGER IF EXISTS audit_event_append_only ON moonpark_pricing_data.audit_event;
CREATE TRIGGER audit_event_append_only
    BEFORE UPDATE OR DELETE ON moonpark_pricing_data.audit_event
    FOR EACH ROW EXECUTE FUNCTION moonpark_pricing_data.audit_event_block_change();
